const params = $input.item.json.body || {};
const ubicacion = params.ubicacion || '';
const palabrasClavesRaw = params.palabrasClaves || 'salon de belleza';
const lat = parseFloat(params.lat);
const lng = parseFloat(params.lng);
const radius = parseInt(params.radius) || 5000;
const limit = parseInt(params.limit) || 15;
const pureKeywordsRaw = params.pureKeywords || 'salon,belleza';

function normalizeStr(str) {
  return (str || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
}
const strictKeywords = pureKeywordsRaw.split(',').map(t => normalizeStr(t.trim())).filter(t => t.length > 0);

// Claves de la API (Puedes usar las de tu .env de React)
const GOOGLE_KEY = 'AIzaSyB7M7AtB5rJ4uNoIKo356_1bPeaP-8iAl8';
const SERPER_KEY = '4e6865059bd96ab759aff3cc5c151b10e0ab6966';
const EVO_URL = 'https://evo.koratflow.agency';
const EVO_INST = 'KoratFlow';
const EVO_KEY = '2C8CB56FF12E-44C0-8002-73BF0A2879AA';

const query = `${palabrasClavesRaw.split(',')[0]} en ${ubicacion}`;
const googleUrl = 'https://places.googleapis.com/v1/places:searchText';
const googleBody = {
  textQuery: query,
  languageCode: 'es',
  locationBias: { circle: { center: { latitude: lat, longitude: lng }, radius: radius } }
};

const placesRes = await fetch(googleUrl, {
  method: 'POST', // Usar POST para places:searchText
  headers: { 'Content-Type': 'application/json', 'X-Goog-Api-Key': GOOGLE_KEY, 'X-Goog-FieldMask': 'places.displayName,places.formattedAddress,places.nationalPhoneNumber,places.rating,places.userRatingCount,places.businessStatus,places.primaryType,places.websiteUri' },
  body: JSON.stringify(googleBody)
});
const placesData = await placesRes.json();
const places = placesData.places || [];

let validLeads = [];
for (const place of places) {
  if (validLeads.length >= limit) break;
  if (!place.nationalPhoneNumber) continue;

  const name = normalizeStr(place.displayName?.text);
  const primaryType = normalizeStr(place.primaryType);
  let isValid = false;
  for (const term of strictKeywords) {
    if (name.includes(term) || primaryType.includes(term)) { isValid = true; break; }
  }
  if (!isValid) continue;

  let telefono = place.nationalPhoneNumber.replace(/\s/g, '');
  let cleanPhone = telefono.replace(/\D/g, '');
  if (cleanPhone.length === 9 && cleanPhone.startsWith('9')) cleanPhone = '51' + cleanPhone;

  let hasWA = true;
  if (EVO_URL && EVO_KEY) {
    try {
      const waRes = await fetch(`${EVO_URL}/chat/whatsappNumbers/${encodeURIComponent(EVO_INST)}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'apikey': EVO_KEY },
        body: JSON.stringify({ numbers: [cleanPhone] })
      });
      const waData = await waRes.json();
      if (Array.isArray(waData) && waData.length > 0 && !waData[0].exists) hasWA = false;
    } catch(e) {}
  }
  if (!hasWA) continue;

  let url_instagram = null, url_facebook = null;
  let info_rrss_text = '';
  if (SERPER_KEY) {
    try {
      const serperRes = await fetch('https://google.serper.dev/search', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'X-API-KEY': SERPER_KEY },
        body: JSON.stringify({ q: `${place.displayName?.text} ${ubicacion}`, gl: 'pe', hl: 'es', num: 5 })
      });
      const serperData = await serperRes.json();
      (serperData.organic || []).forEach(res => {
         info_rrss_text += `[${res.title}] ${res.snippet}\n\n`;
         const lcUrl = res.link.toLowerCase();
         if (lcUrl.includes('instagram.com') && !url_instagram) url_instagram = res.link;
         if ((lcUrl.includes('facebook.com') || lcUrl.includes('fb.com')) && !url_facebook) url_facebook = res.link;
      });
    } catch(e) {}
  }

  validLeads.push({
    nombre_salon: place.displayName?.text || 'Desconocido',
    direccion: place.formattedAddress || 'Sin dirección',
    telefono: telefono,
    calificacion: place.rating || 0,
    total_resenas: place.userRatingCount || 0,
    sitioweb: place.websiteUri || null,
    url_instagram: url_instagram,
    url_facebook: url_facebook,
    estado_contacto: 'Pendiente Análisis IA',
    servicios_detectados: info_rrss_text
  });
}

return validLeads.map(lead => ({ json: lead }));
